#![no_implicit_prelude]

pub enum Payload { A, B, C, D, E, F, G, H, I, J, K, L, M, N, O }

unitary fn keep(q: Q<Payload>) -> Q<Payload> { q }
unitary fn mark(q: Q<Payload>) -> Q<Payload> { global_phase_eighth(q) }

pub unitary fn route(s: Q<Bits<3>>, q: Q<Payload>) -> (Q<Bits<3>>, Q<Payload>) {
    qmatch(s, q) {
        7 => mark, 6 => keep, 5 => mark, 4 => keep,
        3 => mark, 2 => keep, 1 => mark, 0 => keep,
    }
}

